import{_ as a,C as i,c as n,o as l,j as e,G as s,a8 as r,a as d}from"./chunks/framework.8HQ-OgOa.js";const b=JSON.parse('{"title":"Ink Canvas External Protocol (URI Scheme) Specification Document","description":"","frontmatter":{},"headers":[],"relativePath":"en/dev/uri.md","filePath":"en/dev/uri.md"}'),c={name:"en/dev/uri.md"};function h(g,t,p,u,f,m){const o=i("ArticleMetadata");return l(),n("div",null,[t[0]||(t[0]=e("h1",{id:"ink-canvas-external-protocol-uri-scheme-specification-document",tabindex:"-1"},[d("Ink Canvas External Protocol (URI Scheme) Specification Document "),e("a",{class:"header-anchor",href:"#ink-canvas-external-protocol-uri-scheme-specification-document","aria-label":'Permalink to "Ink Canvas External Protocol (URI Scheme) Specification Document"'},"​")],-1)),s(o),t[1]||(t[1]=r('<p>Ink Canvas supports external calls via a custom protocol <code>icc://</code>. With this feature, other applications, webpage scripts, or system shortcuts can remotely control the running state of Ink Canvas.</p><h2 id="activation-method" tabindex="-1">Activation Method <a class="header-anchor" href="#activation-method" aria-label="Permalink to &quot;Activation Method&quot;">​</a></h2><p>Before using the external protocol, it must be enabled in the software settings:</p><ol><li>Open <strong>Settings</strong>.</li><li>Go to the <strong>Advanced Options</strong> panel.</li><li>Find the <strong>External Protocol Call</strong> area.</li><li>Enable the <strong>&quot;Enable External Protocol (icc://)&quot;</strong> switch.</li></ol><blockquote><p><strong>Note</strong>: This action automatically registers the protocol in the system registry for the current user. If you manually turn off this feature, the protocol will be unregistered.</p></blockquote><hr><h2 id="command-list" tabindex="-1">Command List <a class="header-anchor" href="#command-list" aria-label="Permalink to &quot;Command List&quot;">​</a></h2><h3 id="_1-basic-control-commands" tabindex="-1">1. Basic Control Commands <a class="header-anchor" href="#_1-basic-control-commands" aria-label="Permalink to &quot;1. Basic Control Commands&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Full URI</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Fold</strong></td><td style="text-align:left;"><code>icc://fold</code></td><td style="text-align:left;">Enters <strong>collapse mode</strong>. If currently expanded, it clears ink and collapses to the sidebar.</td></tr><tr><td style="text-align:left;"><strong>Unfold</strong></td><td style="text-align:left;"><code>icc://unfold</code></td><td style="text-align:left;">Exits <strong>collapse mode</strong>. If currently collapsed, it expands the floating toolbar.</td></tr><tr><td style="text-align:left;"><strong>Toggle</strong></td><td style="text-align:left;"><code>icc://toggle</code></td><td style="text-align:left;"><strong>Toggles</strong> state. Collapses if expanded, expands if collapsed.</td></tr><tr><td style="text-align:left;"><strong>Show</strong></td><td style="text-align:left;"><code>icc://show</code></td><td style="text-align:left;">Functions identically to <code>unfold</code>, used for compatibility with older commands.</td></tr></tbody></table><h3 id="_2-sidebar-tool-commands" tabindex="-1">2. Sidebar Tool Commands <a class="header-anchor" href="#_2-sidebar-tool-commands" aria-label="Permalink to &quot;2. Sidebar Tool Commands&quot;">​</a></h3><p>The following commands correspond to the quick tools provided in the sidebar under collapse mode.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Full URI</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Pick One</strong></td><td style="text-align:left;"><code>icc://randone</code></td><td style="text-align:left;">Opens the random roll-call window and executes a <strong>single pick</strong>.</td></tr><tr><td style="text-align:left;"><strong>Random Pick</strong></td><td style="text-align:left;"><code>icc://rand</code></td><td style="text-align:left;">Opens the random roll-call window and executes a <strong>random pick</strong>.</td></tr><tr><td style="text-align:left;"><strong>Timer</strong></td><td style="text-align:left;"><code>icc://timer</code></td><td style="text-align:left;">Opens the <strong>timer/countdown</strong> tool.</td></tr><tr><td style="text-align:left;"><strong>Whiteboard</strong></td><td style="text-align:left;"><code>icc://whiteboard</code></td><td style="text-align:left;">Switches to <strong>whiteboard mode</strong> (can also use <code>icc://board</code>).</td></tr></tbody></table><h3 id="_3-tool-state-commands" tabindex="-1">3. Tool State Commands <a class="header-anchor" href="#_3-tool-state-commands" aria-label="Permalink to &quot;3. Tool State Commands&quot;">​</a></h3><p>Used to switch the current annotation tool or query the current tool state. The URI is case-insensitive.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Full URI</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Pen</strong></td><td style="text-align:left;"><code>icc://tool/pen</code> or <code>icc://tool/color</code></td><td style="text-align:left;">Switches to <strong>Pen</strong> (<code>color</code> corresponds to the pen/highlighter entry).</td></tr><tr><td style="text-align:left;"><strong>Mouse</strong></td><td style="text-align:left;"><code>icc://tool/cursor</code></td><td style="text-align:left;">Switches to <strong>Mouse/Cursor</strong> mode.</td></tr><tr><td style="text-align:left;"><strong>Area Eraser</strong></td><td style="text-align:left;"><code>icc://tool/eraser</code></td><td style="text-align:left;">Enters annotation mode first, then switches to the <strong>Area Eraser</strong>.</td></tr><tr><td style="text-align:left;"><strong>Stroke Eraser</strong></td><td style="text-align:left;"><code>icc://tool/eraserbystrokes</code> or <code>icc://tool/eraserstroke</code></td><td style="text-align:left;">Enters annotation mode first, then switches to the <strong>Stroke Eraser</strong>.</td></tr><tr><td style="text-align:left;"><strong>Get Current Tool</strong></td><td style="text-align:left;"><code>icc://tool/state</code></td><td style="text-align:left;">Writes the current tool state to a temporary file for third-party reading. See details below.</td></tr></tbody></table><h4 id="icc-tool-state-return-value-explanation" tabindex="-1"><code>icc://tool/state</code> Return Value Explanation <a class="header-anchor" href="#icc-tool-state-return-value-explanation" aria-label="Permalink to &quot;`icc://tool/state` Return Value Explanation&quot;">​</a></h4><p>Calling this will not return content directly in the protocol layer. Instead, it writes the current tool name to a file:</p><ul><li><strong>File Path</strong>: <code>%TEMP%\\InkCanvasToolState.txt</code> (e.g., <code>C:\\Users\\&lt;Username&gt;\\AppData\\Local\\Temp\\InkCanvasToolState.txt</code>)</li><li><strong>Encoding</strong>: UTF-8, single-line plain text.</li></ul><p>Possible values: <code>cursor</code> (Mouse), <code>pen</code> (Pen), <code>color</code> (Highlighter), <code>eraser</code> (Area Eraser), <code>eraserByStrokes</code> (Stroke Eraser), <code>select</code> (Select), <code>shape</code> (Shape). Defaults to <code>cursor</code> if unrecognized.</p><h3 id="_4-configuration-profile-commands" tabindex="-1">4. Configuration Profile Commands <a class="header-anchor" href="#_4-configuration-profile-commands" aria-label="Permalink to &quot;4. Configuration Profile Commands&quot;">​</a></h3><p>Used to obtain the list of current configuration profiles or switch the active configuration profile via URI. The URI is case-insensitive.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Full URI</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Get Profile List</strong></td><td style="text-align:left;"><code>icc://config-profile/list</code></td><td style="text-align:left;">Writes the names of all current configuration profiles and the active profile to a temporary JSON file for third-party reading.</td></tr><tr><td style="text-align:left;"><strong>Switch Profile</strong></td><td style="text-align:left;"><code>icc://config-profile/switch?name=ProfileName</code></td><td style="text-align:left;">Switches to the specified configuration profile and hot-reloads it, writing the result to a temporary file.</td></tr></tbody></table><h4 id="icc-config-profile-list-return-value-explanation" tabindex="-1"><code>icc://config-profile/list</code> Return Value Explanation <a class="header-anchor" href="#icc-config-profile-list-return-value-explanation" aria-label="Permalink to &quot;`icc://config-profile/list` Return Value Explanation&quot;">​</a></h4><p>Calling this will not return content directly in the protocol layer. Instead, it writes the list to a file:</p><ul><li><strong>File Path</strong>: <code>%TEMP%\\InkCanvasConfigProfileList.json</code></li><li><strong>Encoding</strong>: UTF-8, JSON format.</li></ul><p>Example Content:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;list&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ProfileA&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ProfileB&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Classroom1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ],</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;current&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ProfileA&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li><code>list</code>: Names of all currently saved configuration profiles (string array).</li><li><code>current</code>: The currently active profile name; empty string if never switched via profiles.</li></ul><h4 id="icc-config-profile-switch-explanation" tabindex="-1"><code>icc://config-profile/switch</code> Explanation <a class="header-anchor" href="#icc-config-profile-switch-explanation" aria-label="Permalink to &quot;`icc://config-profile/switch` Explanation&quot;">​</a></h4><ul><li><strong>Query Parameter</strong>: <code>name</code> (required), the name of the profile to switch to. If the profile name contains Chinese characters or special symbols, it must be URL-encoded (e.g., <code>name=%E6%95%99%E5%AE%A41</code>).</li><li><strong>Result File Path</strong>: <code>%TEMP%\\InkCanvasConfigProfileSwitchResult.txt</code></li><li><strong>Encoding</strong>: UTF-8, single-line plain text.</li><li><strong>Possible Content</strong>: <ul><li><code>ok</code>: Switched successfully, hot-reloaded.</li><li><code>error: 缺少参数 name</code> (Missing parameter name): The <code>name</code> parameter was not provided.</li><li><code>error: 方案不存在或应用失败</code> (Profile does not exist or application failed): The specified profile does not exist or application failed.</li></ul></li></ul><p>Examples:</p><ul><li>Switch to the profile named &quot;Classroom1&quot;: <code>icc://config-profile/switch?name=Classroom1</code></li><li>Use encoding when the profile name contains special characters: <code>icc://config-profile/switch?name=%E6%96%B9%E6%A1%88A</code></li></ul><h3 id="_5-advanced-feature-commands-hidden-features" tabindex="-1">5. Advanced Feature Commands (Hidden Features) <a class="header-anchor" href="#_5-advanced-feature-commands-hidden-features" aria-label="Permalink to &quot;5. Advanced Feature Commands (Hidden Features)&quot;">​</a></h3><p>The following features are specifically designed to resolve compatibility issues with third-party sidebar or floating window programs, and are not displayed in the standard settings interface. URIs are case-insensitive; the table below shows lowercase forms.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Full URI</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ThoroughHideOn</strong></td><td style="text-align:left;"><code>icc://thoroughhideon</code></td><td style="text-align:left;"><strong>Enables</strong> &quot;Thorough hide when collapsed&quot;. Once enabled, the main window will be completely invisible when entering collapse mode.</td></tr><tr><td style="text-align:left;"><strong>ThoroughHideOff</strong></td><td style="text-align:left;"><code>icc://thoroughhideoff</code></td><td style="text-align:left;"><strong>Disables</strong> &quot;Thorough hide when collapsed&quot;. Restores the default sidebar edge-tracing mode.</td></tr><tr><td style="text-align:left;"><strong>ThoroughHideToggle</strong></td><td style="text-align:left;"><code>icc://thoroughhidetoggle</code></td><td style="text-align:left;"><strong>Toggles</strong> the enabled/disabled state of the &quot;Thorough hide when collapsed&quot; feature.</td></tr></tbody></table><hr><h2 id="usage-examples" tabindex="-1">Usage Examples <a class="header-anchor" href="#usage-examples" aria-label="Permalink to &quot;Usage Examples&quot;">​</a></h2><h3 id="a-calling-in-a-browser" tabindex="-1">A. Calling in a Browser <a class="header-anchor" href="#a-calling-in-a-browser" aria-label="Permalink to &quot;A. Calling in a Browser&quot;">​</a></h3><p>You can type the URI directly into the browser&#39;s address bar and press Enter, or use hyperlinks in HTML:</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;icc://fold&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Collapse Ink Canvas immediately&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="b-calling-in-the-windows-run-dialog" tabindex="-1">B. Calling in the Windows &quot;Run&quot; Dialog <a class="header-anchor" href="#b-calling-in-the-windows-run-dialog" aria-label="Permalink to &quot;B. Calling in the Windows &quot;Run&quot; Dialog&quot;">​</a></h3><p>Press <code>Win + R</code>, enter <code>icc://toggle</code>, and press Enter.</p><h3 id="c-calling-in-a-batch-file-or-command-line" tabindex="-1">C. Calling in a Batch File or Command Line <a class="header-anchor" href="#c-calling-in-a-batch-file-or-command-line" aria-label="Permalink to &quot;C. Calling in a Batch File or Command Line&quot;">​</a></h3><div class="language-cmd vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">start icc://unfold</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="d-third-party-reading-of-current-tool-state" tabindex="-1">D. Third-Party Reading of Current Tool State <a class="header-anchor" href="#d-third-party-reading-of-current-tool-state" aria-label="Permalink to &quot;D. Third-Party Reading of Current Tool State&quot;">​</a></h3><p>After calling <code>icc://tool/state</code>, read <code>%TEMP%\\InkCanvasToolState.txt</code> to get the current tool name (e.g., <code>pen</code>, <code>cursor</code>, <code>eraser</code>).</p><h3 id="e-third-party-getting-and-switching-profiles" tabindex="-1">E. Third-Party Getting and Switching Profiles <a class="header-anchor" href="#e-third-party-getting-and-switching-profiles" aria-label="Permalink to &quot;E. Third-Party Getting and Switching Profiles&quot;">​</a></h3><ol><li>After calling <code>icc://config-profile/list</code>, read <code>%TEMP%\\InkCanvasConfigProfileList.json</code> to obtain <code>list</code> and <code>current</code>.</li><li>Call <code>icc://config-profile/switch?name=ProfileName</code> to switch profiles, then read <code>%TEMP%\\InkCanvasConfigProfileSwitchResult.txt</code> to determine success (successful if the content is <code>ok</code>).</li></ol><hr><h2 id="developer-notes" tabindex="-1">Developer Notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer Notes&quot;">​</a></h2><h3 id="running-mechanism" tabindex="-1">Running Mechanism <a class="header-anchor" href="#running-mechanism" aria-label="Permalink to &quot;Running Mechanism&quot;">​</a></h3><ol><li><strong>Wake-up Startup</strong>: If Ink Canvas is not yet running, calling the URI will directly start the application and execute the command.</li><li><strong>Inter-Process Communication (IPC)</strong>: If the application is already running, external calls will send instructions to the running instance via system events and temporary files, achieving seamless control.</li></ol><h3 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h3><ul><li>Supports Windows 7 and higher.</li><li>Registry Location: <code>HKEY_CURRENT_USER\\Software\\Classes\\icc</code> (does not require administrator privileges).</li></ul>',54))])}const x=a(c,[["render",h]]);export{b as __pageData,x as default};
